 void create_staging(VkDeviceSize bytes){if(bytes<=staging_size)return;if(mapped)vkUnmapMemory(device,staging_memory);if(staging)vkDestroyBuffer(device,staging,nullptr);if(staging_memory)vkFreeMemory(device,staging_memory,nullptr);VkBufferCreateInfo bi{VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO};bi.size=bytes;bi.usage=VK_BUFFER_USAGE_TRANSFER_SRC_BIT;bi.sharingMode=VK_SHARING_MODE_EXCLUSIVE;vk_ok(vkCreateBuffer(device,&bi,nullptr,&staging),"vkCreateBuffer");VkMemoryRequirements req{};vkGetBufferMemoryRequirements(device,staging,&req);VkMemoryAllocateInfo ai{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};ai.allocationSize=req.size;ai.memoryTypeIndex=memory_type(req.memoryTypeBits,VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT|VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);vk_ok(vkAllocateMemory(device,&ai,nullptr,&staging_memory),"vkAllocateMemory");vk_ok(vkBindBufferMemory(device,staging,staging_memory,0),"vkBindBufferMemory");vk_ok(vkMapMemory(device,staging_memory,0,VK_WHOLE_SIZE,0,&mapped),"vkMapMemory");staging_size=bytes;}
 void create_swapchain(){int width=0,height=0;SDL_GetWindowSizeInPixels(window,&width,&height);if(width<=0||height<=0)return;VkSurfaceCapabilitiesKHR caps{};vk_ok(vkGetPhysicalDeviceSurfaceCapabilitiesKHR(physical,surface,&caps),"surface capabilities");std::uint32_t count=0;vkGetPhysicalDeviceSurfaceFormatsKHR(physical,surface,&count,nullptr);std::vector<VkSurfaceFormatKHR> formats(count);vkGetPhysicalDeviceSurfaceFormatsKHR(physical,surface,&count,formats.data());auto chosen=formats.front();for(auto f:formats)if(f.format==VK_FORMAT_B8G8R8A8_UNORM||f.format==VK_FORMAT_B8G8R8A8_SRGB){chosen=f;break;}format=chosen.format;extent=caps.currentExtent.width!=UINT32_MAX?caps.currentExtent:VkExtent2D{std::clamp(std::uint32_t(width),caps.minImageExtent.width,caps.maxImageExtent.width),std::clamp(std::uint32_t(height),caps.minImageExtent.height,caps.maxImageExtent.height)};std::uint32_t n=std::max(caps.minImageCount,2u);if(caps.maxImageCount)n=std::min(n,caps.maxImageCount);VkSwapchainCreateInfoKHR ci{VK_STRUCTURE_TYPE_SWAPCHAIN_CREATE_INFO_KHR};ci.surface=surface;ci.minImageCount=n;ci.imageFormat=format;ci.imageColorSpace=chosen.colorSpace;ci.imageExtent=extent;ci.imageArrayLayers=1;ci.imageUsage=VK_IMAGE_USAGE_TRANSFER_DST_BIT;ci.imageSharingMode=VK_SHARING_MODE_EXCLUSIVE;ci.preTransform=caps.currentTransform;ci.compositeAlpha=VK_COMPOSITE_ALPHA_OPAQUE_BIT_KHR;ci.presentMode=VK_PRESENT_MODE_FIFO_KHR;ci.clipped=VK_TRUE;vk_ok(vkCreateSwapchainKHR(device,&ci,nullptr,&swapchain),"vkCreateSwapchainKHR");vkGetSwapchainImagesKHR(device,swapchain,&n,nullptr);images.resize(n);vkGetSwapchainImagesKHR(device,swapchain,&n,images.data());initialized.assign(n,false);create_staging(VkDeviceSize(extent.width)*extent.height*4);}
